use vstd::prelude::*;

verus! {

fn hstack(a: Vec<f32>, b: Vec<f32>) -> (res: Vec<f32>)
    requires
        true,
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int|
            0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int|
            0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
        res@ == a@ + b@,
{
    let mut res: Vec<f32> = Vec::with_capacity(a.len() + b.len());

    let a_len = a.len();
    let b_len = b.len();

    let mut i: usize = 0;
    while i < a_len
        invariant
            res@ == a@.subrange(0, i as int),
            i <= a_len,
    {
        res.push(a[i]);
        i += 1;
    }

    let mut j: usize = 0;
    while j < b_len
        invariant
            res@ == a@ + b@.subrange(0, j as int),
            j <= b_len,
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

} // verus!